  "loc.src.data.shiprolelattice.field.identityline.0580d0215ff2": "Knife-range hunter — wins the first pass or dies trying.",
  "loc.src.data.shiprolelattice.field.identityline.05d0d2df7114": "Bulk legs for credits — run the route, do not win the duel.",
  "loc.src.data.shiprolelattice.field.identityline.0940d3b92c5c": "Light scout that teaches every verb without punishing mistakes.",
  "loc.src.data.shiprolelattice.field.identityline.2bb0f678f63a": "Belt workhorse — two mining mounts and room for the haul home.",
  "loc.src.data.shiprolelattice.field.identityline.4be264a391b8": "Patrol-grade brawler — owns mid-range trades, not chases.",
  "loc.src.data.shiprolelattice.field.identityline.6fd4808118b0": "Industrial slab — the field empties before the barge does.",
  "loc.src.data.shiprolelattice.field.identityline.8f21b9ebf1c0": "Sensor nose first — read the lane, then decide to fight or leave.",
  "loc.src.data.shiprolelattice.field.identityline.a8a163c9a296": "The career hinge — outfitting decides the fantasy this week.",
  "loc.src.data.shiprolelattice.field.identityline.ae6332162171": "The fight bends around it — escorts first, then the core.",
  "loc.src.data.shiprolelattice.field.identityline.b3bc2bf665a2": "Wall of guns that advances — not a freighter, not a scout.",
  "loc.src.data.shiprolelattice.field.identityline.be13a24b2359": "Center-mass capital — owns the fight if it gets to plant its feet.",
  "loc.src.data.shiprolelattice.field.identityline.caeb34b47ad8": "Pursuit specialist — spend boost, land the pass, leave.",
  "loc.src.data.shiprolelattice.field.identityline.dd50e1bdcab3": "The credit pump — loaded it wallows; empty it still escapes.",
