  "loc.src.ui.screens.shipyard.field.label.e7d9ceba9160": "vs {String_lattice_counterRoles_0_replace___g}",
  "loc.src.ui.screens.shipyard.field.placeholder.d1a6e3faf4d5": "Search hulls…",
  "loc.src.ui.screens.shipyard.field.text.29f6c2984775": "Cargo and utility capacity matter at the wreck, with shields covering dirty approach vectors.",
  "loc.src.ui.screens.shipyard.field.text.4a672bc43606": "Buy toward the tracked job instead of buying anonymous numbers in a vacuum.",
  "loc.src.ui.screens.shipyard.field.text.9b3bd5eb9d10": "Mining slots and cargo space shorten the loop; shields keep the ore run intact.",
  "loc.src.ui.screens.shipyard.field.text.c99dce9e5503": "Weapons make the clock honest; shields and engines decide whether the contract pays out.",
  "loc.src.ui.screens.shipyard.field.text.cbbd32669e4c": "Track a contract before buying a hull to highlight ships that match the job.",
  "loc.src.ui.screens.shipyard.field.text.dd3030ec8777": "Cargo space makes the payout clean; shields and engines keep the route from becoming an emergency.",
  "loc.src.ui.screens.shipyard.field.text.de1d72afa5c8": "Utility capacity and engines make the sweep fast, while shields forgive hostile lanes.",
  "loc.src.ui.screens.shipyard.field.text.fa165f12fa9f": "Speed, cargo, and enough shielding beat fair fights when patrols get curious.",
  "loc.src.ui.screens.shipyard.field.title.19ab2ce385f9": "Select a hull to inspect purchase options.",
